-- Quest givers and enders from the Forever QuestieDB (Wowhead Forever data) for quests our world DB had no giver or no
-- ender for, so they could not be taken or turned in; only NPCs and objects spawned here. Also the Forever wanted posters
-- for 549 and 567 next to the old NPC givers, and the Uldum Pedestal for 2954. Generated by the 28 Oct quest audit
-- (doc/ForeverQuestGaps.md). Safe to run again.
UPDATE `creature_template` SET `npcflag` = `npcflag` | 2 WHERE `entry` IN (377, 1738, 2784, 2981, 3139, 3142, 3188, 3194, 3304, 3682, 7953, 9077, 9087, 11802, 15481, 257655, 258113, 259118, 264072, 266940, 267009);

-- Pre-quests that QuestieDB and a second source (Wowhead's series list, or Factoruide's checked overrides) agree on, for
-- quests without any chain here. Bandarion Keep needs both The Cult of the Damned and Remnants of War (negative exclusive
-- group: all quests of the group lead to it).
ON DUPLICATE KEY UPDATE `PrevQuestID` = VALUES(`PrevQuestID`);
UPDATE `quest_template_addon` SET `NextQuestID` = 96899, `ExclusiveGroup` = -96897 WHERE `ID` IN (96897, 96898);
